package org.demo.orderservice.privacy;

import org.demo.platformsecurity.privacy.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.demo.platformsecurity.privacy.CommerceRetentionAssessment.*;
import static org.demo.platformsecurity.privacy.InventoryRetentionProtocol.*;
import org.demo.platformsecurity.privacy.InventoryRetentionProtocol.Code;

@Testcontainers
class CommerceRetentionInventoryPostgresIT {
    @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("order_inventory_evidence").withUsername("fixture").withPassword("fixture-only");
    static JdbcTemplate jdbc;static DriverManagerDataSource ds;static DataSourceTransactionManager manager;
    CommerceRetentionJobs jobs;CommerceRetentionBindings bindings;CommerceRetentionInventoryCollector collector;
    final Instant clock=Instant.now().minusSeconds(60).truncatedTo(ChronoUnit.MICROS);
    @BeforeAll static void setup(){ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);}
    @BeforeEach void reset(){jdbc.execute("TRUNCATE orders,commerce_retention_jobs,commerce_retention_evidence,commerce_retention_bindings,commerce_retention_order_state,commerce_privacy_locks,account_privacy_fences RESTART IDENTITY CASCADE");jobs=new CommerceRetentionJobs(ds,manager);bindings=new CommerceRetentionBindings(ds,manager);collector=new CommerceRetentionInventoryCollector(ds,manager);seed(17L);}
    void seed(Long customer){jdbc.update("INSERT INTO orders(id,customer_id,customer_email,total_price,status,inventory_reservation_id,delivery_first_name,delivery_last_name,delivery_street,delivery_postal_code,delivery_city,delivery_country,delivery_phone,delivery_method,fulfillment_type,delivery_cost,discount_amount,idempotency_key,checkout_request_hash,checkout_principal,created_at,updated_at) VALUES(10,?,'fixture@example.test',10,'CANCELLED',13,'Fixture','Buyer','Fixture street','00-001','Fixture city','PL','123456789','STANDARD_COURIER','HOME_DELIVERY',0,0,'fixture-key',?,'fixture',now(),now())",customer,"a".repeat(64));jdbc.update("INSERT INTO order_items(order_id,product_id,product_name,sku,quantity,unit_price,total_price) VALUES(10,1,'Fixture','fixture',2,5,10)");jdbc.update("INSERT INTO order_sagas(order_id,state,next_attempt_at,created_at,updated_at) VALUES(10,'FAILED',NULL,now(),now())");}
    Subject scope(Phase phase){var subject=jobs.prepare(10,phase);assertThat(bindings.prepare(subject,phase)).isEqualTo(CommerceRetentionBindings.Preparation.PREPARED);assertThat(jdbc.update("UPDATE commerce_retention_bindings SET state='BOUND',bound_epoch=1,source_revision=0,invalidated=FALSE")).isEqualTo(7);return subject;}
    long evidence(){return jdbc.queryForObject("SELECT count(*) FROM commerce_retention_evidence",Long.class);}
    InventoryRetentionProtocol.Reply positive(Command c){assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();assertThat(c.reservationId()).isEqualTo(13);assertThat(c.status()).isEqualTo(Terminal.RELEASED);assertThat(c.lines()).containsExactly(new Line(1L,2));return reply(c,State.CONFIRMED,Code.OBSERVED,clock);}
    @Test void derivedExpectationAndStoredSnapshotStayBoundToOwnerAndClock(){var s=scope(Phase.REDACTION);assertThat(collector.collect(s,Phase.REDACTION,this::positive)).isEqualTo(CommerceRetentionInventoryCollector.Result.STORED);assertThat(jdbc.queryForObject("SELECT reconciled_at FROM commerce_retention_evidence WHERE source='INVENTORY'",java.sql.Timestamp.class).toInstant()).isEqualTo(clock);assertThat(jdbc.queryForObject("SELECT customer_id FROM commerce_retention_jobs",Long.class)).isEqualTo(17);assertThat(collector.collect(s,Phase.REDACTION,this::positive)).isEqualTo(CommerceRetentionInventoryCollector.Result.IDEMPOTENT);assertThat(evidence()).isEqualTo(1);}
    @Test void wrongOwnerVersionPhaseAndGenerationNeverReachTransport(){var s=scope(Phase.REDACTION);for(var wrong:List.of(new Subject(10,18,s.orderVersion(),s.chainGeneration()),new Subject(10,17,s.orderVersion()+1,s.chainGeneration()),new Subject(10,17,s.orderVersion(),UUID.randomUUID())))assertThat(collector.collect(wrong,Phase.REDACTION,c->{throw new AssertionError("No HTTP allowed");})).isEqualTo(CommerceRetentionInventoryCollector.Result.WAITING);assertThat(collector.collect(s,Phase.MINIMUM_REMOVAL,c->{throw new AssertionError();})).isEqualTo(CommerceRetentionInventoryCollector.Result.WAITING);assertThat(evidence()).isZero();}
    @Test void businessMutationDuringHttpRejectsTheReply(){var s=scope(Phase.REDACTION);assertThat(collector.collect(s,Phase.REDACTION,c->{jdbc.update("UPDATE order_items SET quantity=1,total_price=5");return positive(c);})).isEqualTo(CommerceRetentionInventoryCollector.Result.STALE);assertThat(evidence()).isZero();}
    @Test void immutableBindingReceiptAndRestoreChangesCannotAdmitAReply(){var s=scope(Phase.REDACTION);assertThatThrownBy(()->jdbc.update("UPDATE commerce_retention_bindings SET source_revision=source_revision+1 WHERE source='INVENTORY'")).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(evidence()).isZero();assertThat(collector.collect(s,Phase.REDACTION,c->{jdbc.update("UPDATE commerce_retention_bindings SET restore_blocked=TRUE WHERE source='INVENTORY'");return positive(c);})).isEqualTo(CommerceRetentionInventoryCollector.Result.STALE);assertThat(evidence()).isZero();}
    @Test void mismatchedOrUnavailableTransportCannotStoreAProof(){var s=scope(Phase.REDACTION);assertThat(collector.collect(s,Phase.REDACTION,c->{throw new IllegalStateException("fixture-private-error");})).isEqualTo(CommerceRetentionInventoryCollector.Result.UNAVAILABLE);assertThat(collector.collect(s,Phase.REDACTION,c->new Reply(11,c.generation(),c.orderVersion(),c.phase(),c.bindingEpoch(),c.sourceRevision(),c.expectationHash(),State.CONFIRMED,Code.OBSERVED,clock))).isEqualTo(CommerceRetentionInventoryCollector.Result.UNAVAILABLE);assertThat(evidence()).isZero();}
    @Test void staleSourceRetiresTheCurrentGenerationWithoutAFalseProof(){var s=scope(Phase.REDACTION);assertThat(collector.collect(s,Phase.REDACTION,c->reply(c,State.UNKNOWN,Code.STALE,null))).isEqualTo(CommerceRetentionInventoryCollector.Result.STALE);assertThat(jdbc.queryForObject("SELECT current FROM commerce_retention_jobs",Boolean.class)).isFalse();assertThat(evidence()).isZero();}
    @Test void explicitUnknownAndBlockedStatesArePreserved(){var s=scope(Phase.REDACTION);assertThat(collector.collect(s,Phase.REDACTION,c->reply(c,State.BLOCKED,Code.ACTIVE,null))).isEqualTo(CommerceRetentionInventoryCollector.Result.STORED);assertThat(jdbc.queryForObject("SELECT state FROM commerce_retention_evidence",String.class)).isEqualTo("BLOCKED");assertThat(collector.collect(s,Phase.REDACTION,this::positive)).isEqualTo(CommerceRetentionInventoryCollector.Result.STALE);assertThat(jdbc.queryForObject("SELECT state FROM commerce_retention_evidence",String.class)).isEqualTo("BLOCKED");}
    @Test void guestOwnershipIsScopedToTheSingleOrder(){jdbc.update("DELETE FROM order_sagas");jdbc.update("DELETE FROM order_items");jdbc.update("DELETE FROM orders");seed(null);var s=scope(Phase.REDACTION);assertThat(s.customerId()).isZero();assertThat(collector.collect(s,Phase.REDACTION,this::positive)).isEqualTo(CommerceRetentionInventoryCollector.Result.STORED);assertThat(jdbc.queryForObject("SELECT customer_id FROM commerce_retention_jobs",Long.class)).isNull();}
    @Test void callerTransactionAndMissingExpectationCannotInvokeHttp(){var s=scope(Phase.REDACTION);new TransactionTemplate(manager).executeWithoutResult(tx->assertThatThrownBy(()->collector.collect(s,Phase.REDACTION,c->{throw new AssertionError();})).hasMessage("INVENTORY_EVIDENCE_CALLER_TRANSACTION"));jdbc.update("UPDATE orders SET inventory_reservation_id=NULL");var next=jobs.prepare(10,Phase.REDACTION);assertThat(collector.collect(next,Phase.REDACTION,c->{throw new AssertionError();})).isEqualTo(CommerceRetentionInventoryCollector.Result.WAITING);}
    @Test void minimumPhaseDoesNotInventARedactionClock(){var s=scope(Phase.MINIMUM_REMOVAL);assertThat(collector.collect(s,Phase.MINIMUM_REMOVAL,c->reply(c,State.UNKNOWN,Code.MISSING_REDACTION,null))).isEqualTo(CommerceRetentionInventoryCollector.Result.STORED);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_evidence WHERE reconciled_at IS NOT NULL OR redacted_at IS NOT NULL",Long.class)).isZero();}
}
